def compute(vars):
    change = vars["v1"] - vars["v2"]
    return {
        "value": change,
        "trace": {
            "capitalized_interest_2019": vars["v1"],
            "capitalized_interest_2018": vars["v2"],
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "currency"
            }
        }
    }
